from pathlib import Path
import json,shutil
import cairosvg
B=Path(__file__).resolve().parent;O=B.parent/'deliverables/通俗化重构版'
audit=[]
for k in ('product','system'):
 a=B/'revisions/round1';a.mkdir(parents=True,exist_ok=True);shutil.copy2(B/f'{k}.md',a/f'{k}.md')
def edit(k,old,new,issue):
 p=B/f'{k}.md';s=p.read_text();assert s.count(old)==1,(k,old,s.count(old));p.write_text(s.replace(old,new));audit.append({'issue':issue,'document':k,'before':old,'after':new,'status':'已修复'})
edit('product','独立回答提供较强的判断依据，提示后回答使用较弱影响；看过完整答案后的复述保留为辅助学习。','在本题订正任务中，独立回答提供较强的判断依据，提示后回答使用较弱影响；看过完整答案后的复述保留为辅助学习。','作答更新适用范围')
edit('system','以“分析一道错题”为例，前端提交题目标识，','题目详情中的直接分析使用一次请求完成处理。以“分析一道错题”为例，前端提交题目标识，','直接请求与后台任务')
edit('system','本题学习中的分析可能需要等待模型返回，因此系统把这类计算放入后台任务。','进入可中断后继续的本题学习时，系统另外创建后台任务，保存多轮订正和回答的进度。这类任务的模型计算可能需要等待，因此由工作器执行。','直接请求与后台任务')
edit('system','查询与修改也分开处理。查看详情、历史和恢复结果不会增加学习记录；提交新答案、确认识别和完成自评会改变业务数据，因此需要版本、请求编号或判题回执。','查询与提交也分开处理。查看详情、历史和恢复结果本身不会新增独立作答或掌握证据；部分读取会刷新访问记录、准备页面内容或检查过期状态。提交新答案、确认识别和完成自评则使用版本、请求编号或判题回执检查本次修改。','查询副作用范围')
edit('system','任务创建时保存来源快照，执行和保存结果时再次比较。学生把2x＋3＝11改为2x－3＝11后，原有解法不能继续作为当前解法，相关任务会被检查，并标记为不再适用于当前材料。历史仍保留当时快照，说明旧回答是在什么条件下产生的。','任务创建时保存当时的来源快照，执行和保存结果时再次比较。学生把2x＋3＝11改为2x－3＝11后，编辑接口删除当前题目原有的解析和诊断；相关本题任务在后续读取或执行时核对来源，并按结果停止使用旧材料。已经创建的任务仍保留其中的题目快照和动作，用于说明旧回答是在什么条件下产生的；这不等于为每次编辑保存一份完整的旧题档案。','旧解析删除与任务快照')
edit('system','图7左侧区分当前题目、原作答、任务和学习记录；右侧区分编辑前后两个版本。保留旧版本用于解释历史，重新检查用于形成当前结果。两者并存，不把旧诊断当作新题的判断。','图7左侧展示当前题目、原作答、任务和学习记录的关系；右侧说明编辑后的处理。已有任务保留旧材料快照，新题需要重新分析。图中的v1、v2表示两次不同内容；系统并未另外建立一套保存每次编辑的完整题目版本库。','旧解析删除与任务快照')
edit('system','主教学阶段由仓颉控制，数据保存在tutor_sessions、tutor_turns、variant_questions和variant_attempts等对象中。','教学会话的变式题由generate_variant准备，已有变式再次使用时由validate_variant检查；独立类似题入口使用第4.3节的generate_practice。两者都需要与原题目标相关，但调用与检查路径不同，不能把独立类似题的四项模型复核套到所有教学变式。\n\nAI讲解完成时，根据实际发生的复述、相似题和情境题结果计算阶段变化量。复述通过增加0.08，未通过减少0.05；相似题通过增加0.12，未通过减少0.08；情境题通过增加0.18，未通过减少0.06。没有进行的阶段不计该项；再减去min(0.06，提示等级×0.02)，将结果限制在0至1之间。这是compute_cognition中的固定分量规则，与第4.1节本题订正任务的概率计算不同。\n\n例如，原估计为0.35，复述和相似题通过、情境题未通过，提示等级为1，则新估计为0.35＋0.08＋0.12－0.06－0.02＝0.47。该结果说明当前程序如何登记本轮表现；后续日期按第4.5节的初次复习规则安排，不能把教学会话结束直接解释为长期掌握。\n\n主教学阶段由仓颉控制，数据保存在tutor_sessions、tutor_turns、variant_questions和variant_attempts等对象中。','教学完成更新与变式检查')
edit('system','后续化学显示专项使用同一铅蓄电池原题，检查题干、选项、解析、下标、电荷和宽度。','后续化学显示专项使用同一铅蓄电池原题，检查题干、选项、解析、下标和宽度。该浏览器样本没有出现电荷标记，电荷规则的验证来自前端局部测试，不能将两类证据混为一次页面检查。','化学浏览器覆盖范围')
edit('system','L₁表示已掌握时出现本次结果的可能程度，L₀表示未掌握时出现该结果的可能程度。','L₁表示已掌握时出现本次结果的可能程度，L₀表示未掌握时出现该结果的可能程度，统计上称为似然。这些是程序默认参数，不是学生实验测得的比例。','术语解释去重')
edit('system','L₁与L₀分别表示在“已经掌握”和“尚未掌握”两种假设下，出现本次回答的可能程度，统计上称为似然。这些是程序的默认参数，不是学生实验测得的比例。','','术语解释去重')
p=O/'figures/09.svg';s=p.read_text().replace('保存旧版本','任务旧快照').replace('历史保留','任务历史').replace('题目版本','题目内容');p.write_text(s)
cairosvg.svg2png(url=str(p),write_to=str(p.with_suffix('.png')),output_width=3000,output_height=2000)
# Keep subsequent regeneration faithful to the reviewed wording.
p=B/'prepare.py';s=p.read_text().replace("'来源标识':'题目版本'","'来源标识':'题目内容'").replace("'冻结快照':'保存旧版本'","'冻结快照':'任务旧快照'").replace("'当前有效结果':'重新分析结果'","'历史保留':'任务历史','当前有效结果':'重新分析结果'");p.write_text(s)
(B/'round2_changes.json').write_text(json.dumps(audit,ensure_ascii=False,indent=2))
print('已落实',len(audit),'项文字与图注修订，另修正图7三个标签')
